const topic = $json.topic;
const system = $json.system_prompt;
const body = {
  model: 'openai/gpt-oss-120b',
  temperature: 0.7,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: 'Topic: ' + topic }
  ]
};
return [{ json: { body: JSON.stringify(body), topic } }];

// Groq -> one item per scene, plus run-wide meta on every item
const raw = $json.choices[0].message.content;
const plan = JSON.parse(raw);
const ascii = s => String(s).replace(/[\u2018\u2019]/g, "'").replace(/[\u201C\u201D]/g, '"').replace(/[\u2010-\u2015]/g, '-').replace(/[\u00A0\u202F\u2009]/g, ' ').replace(/[^\x20-\x7E]/g, '');
const runId = Date.now().toString(36);
const out = [];
plan.scenes.forEach((s, i) => {
  const prompt = ascii(s.image_prompt) + ', vertical 9:16, cinematic, no text, no watermark';
  out.push({ json: {
    run_id: runId,
    index: i,
    voice: ascii(s.voice),
    image_prompt: prompt,
    image_url: 'https://image.pollinations.ai/prompt/' + encodeURIComponent(prompt) + '?width=576&height=1024&nologo=true&nofeed=true&seed=' + (i + 11),
    title: ascii(plan.title), description: ascii(plan.description), tags: plan.tags, scene_count: plan.scenes.length
  }});
});
return out;

// pair each VO duration back with its scene; clip = VO + 0.4s breathing room
const scenes = $('Parse script').all().map(x => x.json);
return $input.all().map((item, i) => {
  const s = scenes[i];
  const dur = Number(item.json.response && item.json.response.duration) || 3;
  const length = Math.ceil((dur + 0.4) * 10) / 10;
  const base = 'https://nca.skynetjoe.com/nca/sf/' + s.run_id + '-' + s.index;
  return { json: Object.assign({}, s, { vo_seconds: dur, length, audio_url: base + '.mp3', hosted_image_url: base + '.jpg' }) };
});

// ffmpeg compose: clip video + VO audio, pad audio to clip length
const clip = $json.response;
const plan = $('Scene plan').all()[$itemIndex].json;
const body = {
  inputs: [ { file_url: clip }, { file_url: plan.audio_url } ],
  outputs: [ { options: [
    { option: '-map', argument: '0:v:0' },
    { option: '-map', argument: '1:a:0' },
    { option: '-vf', argument: 'crop=in_w:in_h-96:0:0,scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,setsar=1' },
    { option: '-c:v', argument: 'libx264' },
    { option: '-preset', argument: 'veryfast' },
    { option: '-crf', argument: '20' },
    { option: '-pix_fmt', argument: 'yuv420p' },
    { option: '-c:a', argument: 'aac' },
    { option: '-af', argument: 'apad' },
    { option: '-t', argument: String(plan.length) }
  ] } ]
};
return { json: { body: JSON.stringify(body), index: plan.index } };

// all scene clips -> ordered list for concatenation (+ carry meta)
const meta = $('Parse script').first().json;
const items = $input.all().map((it, i) => {
  const r = it.json.response;
  const url = Array.isArray(r) ? r[0].file_url : (r.file_url || r);
  return { index: i, url };
});
return [{ json: {
  video_urls: items.map(x => ({ video_url: x.url })),
  title: meta.title, description: meta.description, tags: meta.tags, run_id: meta.run_id
} }];

const video_url = $json.response;
const meta = $('Collect clips').first().json;
const body = {
  video_url,
  settings: {
    style: 'highlight', position: 'middle_center', font_family: 'Arial', font_size: 78,
    line_color: '#FFFFFF', word_color: '#FFD400', outline_color: '#000000', outline_width: 5,
    max_words_per_line: 4, all_caps: true
  }
};
return [{ json: { body: JSON.stringify(body), video_url, title: meta.title, description: meta.description, tags: meta.tags, run_id: meta.run_id } }];

const meta = $('Caption body').first().json;
const r = $json.response;
const final_url = (typeof r === 'string') ? r : (r && r.file_url) || meta.video_url;
return [{ json: { final_url, uncaptioned_url: meta.video_url, title: meta.title, description: meta.description, tags: meta.tags, run_id: meta.run_id } }];

